19	  const int bits_in_word_2 = (int)(sizeof(si_int) * CHAR_BIT) / 2;
20	  const su_int lower_mask = (su_int)~0 >> bits_in_word_2;
21	  r.s.low = (a & lower_mask) * (b & lower_mask);
22	  su_int t = r.s.low >> bits_in_word_2;
